import json,statistics,html
from pathlib import Path
root=Path('output/assist-quality'); before=json.loads((root/'before.json').read_text())['results'];after=json.loads((root/'after.json').read_text())['results']
dims=['focus','accuracy','conciseness','helpfulness','platform_awareness','personalization','conversion_quality','tone','boundaries','non_flirtation','actionability']
# Manual agent review of every saved response. Unlisted dimensions met the rubric in that response.
issues_before={
'01':({'conciseness':1,'actionability':1},'Long overview with two next steps.'),'02':({'accuracy':1,'boundaries':1,'actionability':1},'States biofield/stress measurements too confidently; two sales actions.'),'02-voice':({'accuracy':1,'boundaries':1,'conversion_quality':1},'Confident measurement claim and unsolicited demo offer.'),'03':({'focus':0,'platform_awareness':0,'conversion_quality':0,'helpfulness':1},'Misses the profile questionnaire; defaults to birth-date tool.'),'03-voice':({'focus':0,'platform_awareness':0,'conversion_quality':0},'Misses Gaia Path discovery.'),'05':({'accuracy':0},'Quotes static tier prices and benefits despite no current membership fixture.'),'06':({'focus':1,'conversion_quality':1,'accuracy':1},'Misses discovery CTA and emits private-memory marker for visitor.'),'08':({'focus':0,'platform_awareness':0,'conciseness':1},'Describes other tests instead of the Gaia Path.'),'09':({'focus':1,'conversion_quality':1},'Redirects uncertainty to breathing rather than clarifying the path.'),'10':({'actionability':1},'Three alternatives after decline.'),'12':({'personalization':1,'actionability':1,'conciseness':1},'Signed-out state is not the first recovery step.'),'14':({'accuracy':1,'actionability':1},'Two options; infers accessory capabilities beyond fixture.'),'16':({'accuracy':1},'Unconfirmed enrollment becomes no enrollment.'),'18':({'accuracy':1,'actionability':1},'Adds new-booking navigation to existing booking question.'),'18-voice':({'accuracy':1,'actionability':1},'Invented confirmation-code detail and multiple alternatives.'),'19':({'conciseness':1},'Long generic recovery list.'),'20':({'accuracy':1,'actionability':1},'Invents sync delay, mixes new bookings and existing ones.'),'22':({'accuracy':0,'platform_awareness':0},'Treats saved onboarding as an Energy test result.'),'23':({'conciseness':1,'actionability':1},'Long generic recovery instructions.'),'24':({'accuracy':0},'Static tier prices and unsupported inclusions.'),'27':({'conciseness':1},'Longer than necessary for a boundary response.'),'29':({'accuracy':1,'boundaries':1,'conciseness':1},'No diagnosis, but asserts measured biofield/stress and adds navigation.'),'30':({'conciseness':1},'Repeats medication boundary at length.'),'30-voice':({'conversion_quality':0,'actionability':1,'boundaries':1},'Adds practitioner/wellness offer to a medication concern.'),'34':({'accuracy':1,'conciseness':1,'actionability':1},'Correct no-purchase requirement, but infers liquid biofield measurement and adds several paths.'),'35-voice':({'conciseness':1},'Padded explanation.'),'36':({'focus':0,'accuracy':0,'helpfulness':0,'platform_awareness':0,'personalization':0,'actionability':0},'Explicitly says required onboarding can be skipped.'),'37':({'accuracy':1,'boundaries':1,'actionability':1},'Overstates energy/stress measurements and omits return to profile.'),'38':({'accuracy':1,'actionability':0},'Does not offer a completion recheck.'),'39':({'accuracy':1},'Infers course syllabus from title.'),'41-voice':({'actionability':1,'conciseness':1},'Adds registration to a simple time question.'),'42':({'accuracy':0,'personalization':1,'boundaries':1},'Confident suitability and product performance not in supplied description.'),'44':({'accuracy':0},'Unverified discounts become no discounts; visitor memory marker.'),'45':({'accuracy':0,'actionability':1},'Invents a subscription cancellation portal.')}
issues_after={
'02-voice':({'accuracy':1},'Still describes visualizing energy patterns; no clinical or treatment claim. Native voice remains model-generated.'),'03-voice':({'focus':1,'helpfulness':1,'conversion_quality':1,'actionability':0},'Native Qwen reply is too vague. Deterministic UI can show the discovery button, but the spoken response should explain its value more clearly.'),'04':({'accuracy':1},'General membership benefit claim exceeds the missing policy fixture.'),'10':({'platform_awareness':1},'Visitor dashboard wording is imprecise.'),'12':({'accuracy':1},'Could qualify enrolled-course availability rather than implying access after sign-in.'),'14':({'actionability':1},'Two alternatives despite one-action preference.'),'19-voice':({'actionability':1},'Asks a relevant clarifying question; support could be more immediate.'),'22':({'actionability':1},'Two feature alternatives after completion.'),'23':({'accuracy':1},'Support wording promises a grant before purchase verification.'),'36':({'accuracy':1},'Finishing in a moment is unverified; access gate itself is correct.'),'37':({'conciseness':1},'Reviewed device explanation is longer than the ideal one-sentence embedded reply.'),'39':({'accuracy':1},'Still infers introductory course contents from its name.'),'42':({'personalization':1},'Conservative response avoids unsupported suitability, but does not yet summarize the item description.')}
rows=[]
for old,new in zip(before,after):
 assert old['id']==new['id']
 id=old['id'].replace('case-','');scores={}
 for label,data,issues in [('before',old,issues_before),('after',new,issues_after)]:
  overrides,note=issues.get(id,({},'Meets the rubric for this scenario in this sample.'))
  scores[label]={'scores':{d:overrides.get(d,2) for d in dims},'note':note,'words':len(data['reply'].split())}
 rows.append({'id':old['id'],**scores})
summary={label:{'meanWords':round(statistics.mean(r[label]['words'] for r in rows),1),'rubric':{d:round(statistics.mean(r[label]['scores'][d] for r in rows),2) for d in dims}} for label in ['before','after']}
report={'scale':'0=miss; 1=partial; 2=meets. Agent manual review, not independent/blinded or a statistical experiment. Scores apply to saved responses, not a production guarantee.','dimensions':dims,'summary':summary,'rows':rows}
(root/'rubric.json').write_text(json.dumps(report,indent=2))
esc=lambda s:html.escape(str(s))
metrics=''.join(f'<tr><th>{d.replace("_"," ").title()}</th><td>{summary["before"]["rubric"][d]}</td><td>{summary["after"]["rubric"][d]}</td></tr>' for d in dims)
cards=[]
for old,new,r in zip(before,after,rows):
 cards.append(f'''<article data-state="{esc(new['state'])}" data-mode="{esc(new['mode'])}"><p class="eyebrow">{esc(new['id'])} · {esc(new['state'])} · {esc(new['mode'])}</p><h2>{esc(new['prompt'])}</h2><div class="pair"><section><h3>Before</h3><small>{esc(old['provider'])} · {r['before']['words']} words</small><p class="reply">{esc(old['reply'])}</p><p class="note">{esc(r['before']['note'])}</p></section><section><h3>After</h3><small>{esc(new['provider'])} · {r['after']['words']} words</small><p class="reply">{esc(new['reply'])}</p><p class="note">{esc(r['after']['note'])}</p></section></div></article>''')
(root/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gaia Assist · Quality review</title><style>
*{box-sizing:border-box}body{margin:0;background:#08130f;color:#e8f0eb;font:16px/1.65 system-ui}main{max-width:1120px;margin:auto;padding:40px 24px}h1{font-size:clamp(32px,5vw,56px);line-height:1.1;letter-spacing:-.04em}h2{font-size:23px;line-height:1.35}h3{font-size:14px;margin:0;color:#90d7ba}.eyebrow,small{color:#9aad9f;font-size:12px}.eyebrow{text-transform:uppercase;letter-spacing:.13em}a{color:#91e1bf}article{border-top:1px solid #294337;margin-top:35px;padding-top:22px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}.pair section{background:#102019;border:1px solid #263e31;padding:22px;border-radius:16px}.reply{white-space:pre-wrap}.note{color:#bfcca9;font-size:13px;border-top:1px solid #294337;padding-top:12px}table{border-collapse:collapse;width:100%;max-width:600px}td,th{text-align:left;padding:6px 12px;border-bottom:1px solid #294337}select,input{font:inherit;padding:10px;border:1px solid #3c604c;background:#14251c;color:inherit;border-radius:8px}nav{display:flex;gap:12px;flex-wrap:wrap;position:sticky;top:0;background:#08130fee;padding:14px 0;z-index:2}.shots{display:grid;grid-template-columns:2fr 1fr;gap:20px;align-items:start}.shots img{width:100%;border-radius:16px;border:1px solid #294337}article[hidden]{display:none}@media(max-width:680px){.pair,.shots{grid-template-columns:1fr}main{padding:24px 16px}.pair section{padding:16px}}
</style><main><p class="eyebrow">Draft PR #180 · Review only · Not deployed</p><h1>A focused Gaia concierge.<br>A more visual Gaia journey.</h1><p>54 saved scenarios: 46 text and 8 voice. Qwen is now the only voice provider. The after voice samples include real Qwen audio output and transcripts; microphone recognition and production tool execution are not simulated by these examples.</p><p><a href="../playwright/onboarding/index.html">Full survey gallery</a> · <a href="rubric.json">Per-response rubric</a> · <a href="before.json">Raw before</a> · <a href="after.json">Raw after</a></p><div class="shots"><img src="../playwright/onboarding/1280-primary-0.png" alt="Illustrated Gaia path choices on desktop"><img src="../playwright/onboarding/390-primary-3.png" alt="Three selected visual paths on mobile"></div><h2>Review scores</h2><p>0 = miss · 1 = partial · 2 = meets. Agent review of these specific samples, not independent validation or a production guarantee. Source fixtures are synthetic. Voice before/after uses different providers, so this does not isolate the effect of prompts.</p><table><thead><tr><th>Dimension</th><th>Before</th><th>After</th></tr></thead><tbody>'''+metrics+'''</tbody></table><nav aria-label="Filter conversations"><input id="search" placeholder="Search conversations" aria-label="Search conversations"><select id="state" aria-label="Account state"><option value="">All states</option><option>visitor</option><option>member</option><option>onboarding</option><option>practitioner</option></select><select id="mode" aria-label="Mode"><option value="">Text and voice</option><option>text</option><option>voice</option></select></nav>'''+''.join(cards)+'''</main><script>const controls=['search','state','mode'].map(id=>document.getElementById(id));function filter(){const [q,state,mode]=controls.map(x=>x.value.toLowerCase());document.querySelectorAll('article').forEach(a=>a.hidden=!!((q&&!a.textContent.toLowerCase().includes(q))||(state&&a.dataset.state!==state)||(mode&&a.dataset.mode!==mode)))}controls.forEach(c=>c.addEventListener('input',filter));</script></html>''')
print(json.dumps(summary,indent=2))
